use super::*;
fn request()->Request{serde_json::from_slice(&fs::read(std::env::var("ALIFE_CORNER_TEST_REQUEST").expect("external request path")).unwrap()).unwrap()}

#[test]
#[ignore = "requires explicitly supplied private research inputs"]fn commonparent_and_all9_policy_exact_private_Adam_cold(){let r=request();let(h,t,g,_)=load(&r).unwrap();let raw=bytes(&h.checkpoint(&t).unwrap()).unwrap();let p:Value=serde_json::from_slice(&fs::read(std::env::var("ALIFE_CORNER_PROPOSALS").expect("external proposals path")).unwrap()).unwrap();for v in p["variants"].as_array().unwrap(){let edits:Vec<(u32,u32)>=serde_json::from_value(v["weight_edits_bits"].clone()).unwrap();let(c,n,_) =policy(&h,&t,&g,&edits).unwrap();let mut expected=h.checkpoint(&t).unwrap();expected.founder_weight_digest=c.checkpoint(&n).unwrap().founder_weight_digest;assert_eq!(bytes(&expected).unwrap(),bytes(&c.checkpoint(&n).unwrap()).unwrap());assert_eq!(raw,bytes(&h.checkpoint(&t).unwrap()).unwrap());}}
#[test]
#[ignore = "requires explicitly supplied private research inputs"]fn native_wall_blocks_direct_and_continuous_detour_clear(){let r=request();let(h,t,g,_)=load(&r).unwrap();let own=identity(&h,&t,&g,Recipe::Candidate).unwrap();for id in [0u8,1]{let mut s=h.snapshot();let(goal,event)=fixture(&mut s,&t,&g,id).unwrap();let agent=s.world().organism_registry().get(own).unwrap().world_entity_id();let a=s.world().entity(agent).unwrap();let origin=a.position;let yaw=a.body_yaw;let radius=s.world().terrain().map_or(LocomotionLimits::default().body_radius,|t|t.limits().body_radius);let command=ActionCommand::structured(own,ActionId(101),ActionKind::Move,ActionTarget::new(Some(goal),None),Intensity::new(1.).unwrap(),DurationTicks::new(1),Confidence::new(1.).unwrap(),0,None,None,None).unwrap();for _ in 0..64{s.world_mut().apply_command(&command).unwrap();}let p=s.world().entity(agent).unwrap().position;let f=(p.x-origin.x)*yaw.cos()+(p.z-origin.z)*yaw.sin();assert!(f<1.2,"directnativeApproachpenetratedwall");assert!(!s.world().safe_food_eat_is_available(own,goal));let wall=WorldEntityId(event["walls"][0].as_u64().unwrap());let wallbefore=object(s.world().entity(wall).unwrap());let grab=ActionCommand::structured(own,ActionId(211),ActionKind::Interact,ActionTarget::new(Some(wall),None),Intensity::new(1.).unwrap(),DurationTicks::new(1),Confidence::new(1.).unwrap(),0,None,None,None).unwrap();let result=s.world_mut().apply_command(&grab).unwrap();assert!(!result.execution.succeeded);assert_eq!(bytes(&wallbefore).unwrap(),bytes(&object(s.world().entity(wall).unwrap())).unwrap());let sign=if id==0{1.}else{-1.};let route=[(0f32,0f32),(0.,sign*1.6),(2.6,sign*1.6),(2.6,0.)];let walls=event["walls"].as_array().unwrap();for pair in route.windows(2){for k in 0..=400{let q=k as f32/400.;let f=pair[0].0+(pair[1].0-pair[0].0)*q;let l=pair[0].1+(pair[1].1-pair[0].1)*q;let p=Vec3f::new(origin.x+f*yaw.cos()-l*yaw.sin(),origin.y,origin.z+f*yaw.sin()+l*yaw.cos());for w in walls{let o=s.world().entity(WorldEntityId(w.as_u64().unwrap())).unwrap();let d=((p.x-o.position.x).powi(2)+(p.z-o.position.z).powi(2)).sqrt();assert!(d>radius+o.radius,"no bodyradiusclear detour");}}}}}
#[test]
#[ignore = "requires explicitly supplied private research inputs"]fn fixture_private_and_native_warmcold_observer(){let r=request();let(h,t,g,_)=load(&r).unwrap();let mut s=h.snapshot();fixture(&mut s,&t,&g,0).unwrap();let own=identity(&s,&t,&g,Recipe::Candidate).unwrap();let out=std::env::temp_dir().join(format!("alife-corner-qual-{}",std::process::id()));fs::create_dir(&out).unwrap();let v=run_inner(&mut s,&t,&g,&out,8,true,1.,Recipe::Candidate,&[],false,false).unwrap();assert_eq!(v["completed_intervals"],8);assert!(alive(&h,own));}
